const esc=escape;
function headMeta(html,{title,description,path}){
 html=html.replace(/<title>[\s\S]*?<\/title>/,`<title>${esc(title)}</title>`).replace(/<meta name="description" content="[^"]*">/,`<meta name="description" content="${esc(description)}">`).replace(/<meta name="robots" content="[^"]*">/,'<meta name="robots" content="index,follow">').replace(/<meta property="og:title" content="[^"]*">/,`<meta property="og:title" content="${esc(title)}">`).replace(/<meta property="og:description" content="[^"]*">/,`<meta property="og:description" content="${esc(description)}">`).replace(/<link rel="canonical" href="[^"]*">/,`<link rel="canonical" href="https://www.vdalo.tech${path}">`).replace(/<meta property="og:url" content="[^"]*">/,`<meta property="og:url" content="https://www.vdalo.tech${path}">`);
 return html.replace('</head>','<link rel="stylesheet" href="/tools.css"><script src="/tools.js" defer></script>' + (pageIconPath(path) ? pageDesignStyles : '') + '</head>');
}
const shell=()=>renderPage({origin:'https://www.vdalo.tech',full:false});
