const toolCatalogIconForHref=(href='')=>{
 const rules=[['profitability','chart'],['pms-checklist','checklist'],['qr-studio','qr'],['tourist-tax','tax'],['booking-calendar','calendar'],['direct-booking','calendar'],['room-cost','room'],['housekeeping','broom'],['admin-time','clock'],['website-checklist','website'],['guest-message','chat'],['cancellation','calendar'],['hotel-review','quote'],['resources','guide']];
 const icon=rules.find(([key])=>href.includes(key))?.[1]||'guide';
 return `<span class="tool-card-icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${toolCatalogIconPaths[icon]}</svg></span>`;
};
const addToolCatalogIcons=html=>html.replace(/<article class="tool-card">[\s\S]*?<\/article>/g,card=>{
 if(card.includes('tool-card-icon'))return card;
 const href=card.match(/href="([^"]+)"/)?.[1]||'';
 return card.replace('<h3>',`${toolCatalogIconForHref(href)}<h3>`);
});
