function renderPrintableWorksheet({heading,details,columns,rows,totalLabel,footerLines=[]}){
 const headers=columns.map(label=>`<th scope="col">${esc(label)}</th>`).join('');
 const row=`<tr>${'<td></td>'.repeat(columns.length)}</tr>`;
 const totals=totalLabel?`<tfoot><tr><th scope="row">${esc(totalLabel)}</th>${'<td></td>'.repeat(columns.length-1)}</tr></tfoot>`:'';
 return `<section class="tool-method tool-print-sheet" aria-labelledby="worksheet-print-title">
  <h2 id="worksheet-print-title">${esc(heading)}</h2>
  ${details.map(line=>`<p>${esc(line)}</p>`).join('')}
  <div class="tool-print-scroll" role="region" aria-labelledby="worksheet-print-title" tabindex="0">
   <table aria-labelledby="worksheet-print-title"><thead><tr>${headers}</tr></thead><tbody>${row.repeat(rows)}</tbody>${totals}</table>
  </div>
  ${footerLines.map(line=>`<p>${esc(line)}</p>`).join('')}
 </section>`;
}

export function renderWorksheetTool(tool){
 const list=tool.steps.map(step=>`<li>${esc(step)}</li>`).join('');
 const faq=tool.faq.map(([question,answer])=>`<details><summary>${esc(question)}</summary><p>${esc(answer)}</p></details>`).join('');
 const links=tool.related.map(([href,label])=>`<li><a href="${esc(href)}">${esc(label)}</a></li>`).join('');
 const printButton=tool.print?'<button class="tool-secondary" type="button" data-worksheet-print hidden>Надрукувати бланк</button>':'';
 const printSheet=tool.print?renderPrintableWorksheet(tool.print):'';
 const priceRule=tool.rule?`<h3>${esc(tool.ruleTitle||'Як працюють винятки')}</h3><p>${esc(tool.rule)}</p>`:'';
 const html=headMeta(shell(),tool);
 return html.replace(/<main id="main">[\s\S]*?<\/main>/,`<main id="main" class="tool-page worksheet-tool-page"><div class="tool-wrap">
  ${breadcrumb(tool.heading)}
  <header class="tool-hero design-tool-hero">${pageMark(tool.path)}<p class="tool-kicker">ШАБЛОН ДЛЯ ГОТЕЛЮ</p><h1>${esc(tool.heading)}</h1><p>${esc(tool.description)}</p><a class="tool-primary" href="#instrument">${esc(tool.heroAction||'До бланка')} <span aria-hidden="true">↓</span></a></header>
  <section class="tool-method worksheet-download" id="instrument"><h2>Бланк і заповнений приклад</h2><p>У файлі два аркуші. Почніть із «Прикладу», після цього заповніть «Бланк» для свого об’єкта.</p><div class="tool-actions"><a class="tool-primary" href="/downloads/hotel/${esc(tool.file)}" download>${esc(tool.downloadLabel)}</a>${printButton}</div></section>
  ${printSheet}
  <section class="tool-method"><h2>${esc(tool.stepsTitle||'Як заповнити шаблон')}</h2><ol>${list}</ol>${priceRule}<h3>${esc(tool.exampleTitle||'Робочий приклад')}</h3><p>${esc(tool.example)}</p></section>
  <section class="tool-faq"><h2>Поширені запитання</h2>${faq}</section>
  <section class="tool-sources"><h2>Матеріали за темою</h2><ul>${links}<li><a href="/resources">Бібліотека шаблонів готелю</a></li></ul></section>
 </div></main>`);
}

export const pmsCostPath='/tools/pms-cost-calculator/';
const pmsCostTitle='Калькулятор повної вартості готельної PMS';
