function budgetField(key,label,{max=1000000,step='0.01',min=0,required=false}={}){
 return `<label><span>${label}</span><input type="number" min="${min}" max="${max}" step="${step}" inputmode="${step==='1'?'numeric':'decimal'}" data-budget-field="${key}"${required?' required':''}></label>`;
}

