function renderOperationField([key,label,value,min,max,step=0.01,type='number']){
 const attributes=type==='date'
  ?(value?' required':'')
  :` min="${min}" max="${max}" step="${step}" inputmode="${step===1?'numeric':'decimal'}" required`;
 return `<label><span>${esc(label)}</span><input type="${type}" data-ops-field="${key}" value="${esc(value)}"${attributes}></label>`;
}

export function renderOperationCalculator(tool){
 const html=headMeta(shell(),{...tool,title:tool.title+' | VDALO'})
  .replace('</head>',`<script type="module" src="/v1/operation-calculators.js?v=${assetVersion('operation-calculators.js')}"></script></head>`);
 const fields=tool.groups.map(([heading,items])=>`<fieldset><legend>${esc(heading)}</legend><div class="tool-form-grid">${items.map(renderOperationField).join('')}</div></fieldset>`).join('');
 const results=tool.results.map(([heading,rows])=>`<article><h3>${esc(heading)}</h3><dl>${rows.map(([key,label])=>`<div><dt>${esc(label)}</dt><dd data-ops-output="${key}"></dd></div>`).join('')}</dl></article>`).join('');
 const samples=tool.examples.map(([key,label])=>`<button class="tool-secondary" type="button" data-ops-example="${key}" data-ops-enhancement hidden>${esc(label)}</button>`).join('');
 const quote=tool.customerQuote?'<div class="ops-quote"><label>Пропозиція для організатора<textarea data-ops-quote readonly rows="8"></textarea></label><button class="tool-secondary" type="button" data-ops-copy>Скопіювати пропозицію</button><p data-ops-feedback role="status"></p></div>':'';
 return html.replace(/<main id="main">[\s\S]*?<\/main>/,`<main id="main" class="tool-page"><div class="tool-wrap">
  ${breadcrumb(tool.title)}
  <header class="tool-hero design-tool-hero">${pageMark(tool.path)}<p class="tool-kicker">${esc(tool.kicker||'КАЛЬКУЛЯТОР ДЛЯ ГОТЕЛЮ')}</p><h1>${esc(tool.title)}</h1><p>${esc(tool.description)}</p><a class="tool-primary" href="#instrument">${esc(tool.cta)} <span aria-hidden="true">↓</span></a></header>
  <form id="instrument" class="advanced-tool pms-budget" data-operation-calculator="${tool.key}" novalidate>
   <p>${esc(tool.note)}</p>${fields}
   <p class="tool-inline-error" data-ops-error role="alert"></p>
   <div class="tool-actions"><button class="tool-primary" type="submit" data-ops-enhancement hidden>Порахувати</button>${samples}</div>
   <noscript><p>Для інтерактивного підрахунку ввімкніть JavaScript. Приклад розрахунку наведено нижче.</p></noscript>
   <section class="budget-results" data-ops-results hidden aria-labelledby="ops-result-heading"><h2 id="ops-result-heading" tabindex="-1">Результат розрахунку</h2><div class="budget-results-grid">${results}</div>${quote}</section>
  </form>
  ${tool.method.map(([heading,body])=>`<section class="tool-method"><h2>${esc(heading)}</h2><p>${esc(body)}</p></section>`).join('')}
  <section class="tool-faq"><h2>Поширені запитання</h2><details><summary>${esc(tool.faq[0])}</summary><p>${esc(tool.faq[1])}</p></details></section>
  <section class="tool-sources"><h2>Матеріали за темою</h2><ul>${tool.links.map(([href,label])=>`<li><a href="${esc(href)}">${esc(label)}</a></li>`).join('')}</ul></section>
 </div></main>`);
}

export function renderToolsIndex(){
 let html=headMeta(shell(),{title:'Інструменти для готельєрів | VDALO',description:'Практичні інструменти VDALO: калькулятори для готелю, чекліст вибору PMS, QR Studio та бібліотека готових шаблонів для команди.',path:'/tools/'});
 html=html.replace(/<main id="main">[\s\S]*?<\/main>/,`<main id="main" class="tool-page"><div class="tool-wrap">${breadcrumb()}<header class="tool-hero"><p class="tool-kicker">ПРАКТИЧНІ ІНСТРУМЕНТИ VDALO</p><h1>Практичні інструменти для управління готелем</h1><p>Порахуйте фінансовий сценарій, перевірте процес або підготуйте матеріал для гостей. Оберіть інструмент під задачу.</p></header><section class="tool-catalog" aria-labelledby="tool-catalog-title"><h2 id="tool-catalog-title">Оберіть інструмент</h2><div class="tool-catalog-grid"><article class="tool-card"><span class="tool-card-tag">КАЛЬКУЛЯТОР</span><h3>Виручка, RevPAR та витрати готелю</h3><p>Введіть показники об’єкта й оцініть місячну виручку, RevPAR, комісію каналів та енерговитрати.</p><a class="tool-primary" href="/tools/hotel-profitability-calculator/">Відкрити калькулятор <span aria-hidden="true">↗</span></a></article><article class="tool-card"><span class="tool-card-tag">ІНТЕРАКТИВНИЙ ЧЕКЛІСТ</span><h3>Чекліст вибору PMS: 25 критеріїв</h3><p>Порівняйте до трьох PMS за однаковими критеріями та збережіть власні оцінки й нотатки у браузері.</p><a class="tool-primary" href="/tools/pms-checklist/">Відкрити інструмент <span aria-hidden="true">↗</span></a></article><article class="tool-card"><span class="tool-card-tag">QR-ГЕНЕРАТОР</span><h3>QR-коди для Wi-Fi, бронювання та меню</h3><p>Створіть гостьовий QR-код, додайте логотип і оформлення закладу та завантажте файл для екрана або друку.</p><a class="tool-primary" href="/tools/qr-studio/">Відкрити QR Studio <span aria-hidden="true">↗</span></a></article><article class="tool-card"><span class="tool-card-tag">ДОВІДНИК І КАЛЬКУЛЯТОР</span><h3>Туристичний збір за громадою</h3><p>Перевірте місцеве джерело, ставку та період її дії. Розрахунок доступний для перевірених правил.</p><a class="tool-primary" href="/tourist-tax/">Перейти до туристичного збору <span aria-hidden="true">↗</span></a></article></div></section><section class="tool-method tool-index-guide" aria-labelledby="tool-index-guide-title"><p class="tool-card-tag">ЯК ОБРАТИ ІНСТРУМЕНТ</p><h2 id="tool-index-guide-title">Почніть із конкретного завдання готелю</h2><div class="tool-index-grid"><article><h3>Оцінити фінансовий сценарій</h3><p>Калькулятор моделює виручку, RevPAR, комісію OTA та енерговитрати за введеними параметрами. Перегляньте склад розрахунку, щоб співвіднести результат зі звітністю вашого готелю. <a href="/tools/hotel-profitability-calculator/">Перейти до калькулятора</a>.</p></article><article><h3>Порівняти системи керування</h3><p>Чекліст допоможе провести демонстрацію PMS за 25 критеріями та зібрати власні висновки для команди. <a href="/tools/pms-checklist/">Відкрити чекліст PMS</a>.</p></article><article><h3>Підготувати інформацію для гостя</h3><p>QR Studio створює код для Wi-Fi, посилання на бронювання, меню чи інструкції. QR-код відкриває заданий вміст. Щоб гість перейшов до замовлення або бронювання, додайте посилання на сервіс, який приймає такі запити. <a href="/tools/qr-studio/">Створити QR-код</a>.</p></article></div><p class="tool-index-note">Використовуйте розрахунки як орієнтир і вводьте власні припущення. Не додавайте персональні дані гостей або секрети доступу.</p></section><p class="tool-note">Калькулятор показує оцінку на основі введених вами припущень. Перед рішенням зіставте власні оцінки з демонстрацією, договором і повною вартістю системи.</p></div></main>`);
 html=html.replace('<p class="tool-note">','<section class="tool-added-catalog" aria-labelledby="tool-added-title"><h2 id="tool-added-title">Ще інструменти для щоденної роботи</h2><div class="tool-catalog-grid"><article class="tool-card"><h3>Економіка OTA та прямих бронювань</h3><p>Порівняйте внесок одного завершеного проживання за власними витратами каналу.</p><a class="tool-primary" href="/tools/direct-booking-cost-calculator/">Порівняти канали ↗</a></article><article class="tool-card"><h3>Собівартість номера та беззбитковість</h3><p>Оцініть витрати на номероніч і потрібний рівень завантаження.</p><a class="tool-primary" href="/tools/hotel-room-cost-calculator/">Розрахувати сценарій ↗</a></article><article class="tool-card"><h3>Картка перевірки номера</h3><p>Позначте критичні питання, надрукуйте картку або збережіть її локально.</p><a class="tool-primary" href="/tools/housekeeping-checklist/">Перевірити номер ↗</a></article></div></section><p class="tool-note">');
 html=html.replace('<p class="tool-note">','<section class="tool-library-link"><h2>Готові матеріали для команди</h2><p>Картки приймання, шаблони передавання зміни та інші практичні файли можна переглянути в <a href="/resources">бібліотеці шаблонів для готелю</a>.</p></section><p class="tool-note">');
 html=html.replace('<p class="tool-note">','<section class="tool-added-catalog" aria-labelledby="tool-extra-title"><h2 id="tool-extra-title">Інструменти для операційної роботи</h2><div class="tool-catalog-grid"><article class="tool-card"><h3>Оцінка часу адміністратора</h3><p>Порівняйте введені хвилини на повторювані процеси до й після зміни.</p><a class="tool-primary" href="/tools/hotel-admin-time-calculator/">Оцінити час ↗</a></article><article class="tool-card"><h3>Самоперевірка сайту готелю</h3><p>Перевірте шлях гостя вручну на телефоні й комп’ютері та сформуйте список дій.</p><a class="tool-primary" href="/tools/hotel-website-checklist/">Відкрити чекліст ↗</a></article></div></section><p class="tool-note">');
 html=html.replace('<p class="tool-note">','<section class="tool-library-link"><h2>Повідомлення гостям</h2><p>Підготуйте редаговану чернетку українською чи англійською без автоматичного надсилання. <a href="/tools/guest-message-builder/">Відкрити конструктор тексту</a>.</p></section><p class="tool-note">');
 html=html.replace('<p class="tool-note">','<section class="tool-added-catalog"><h2>Інструменти для планування та аналізу</h2><div class="tool-catalog-grid"><article class="tool-card"><h3>Навантаження прибирання</h3><p>Зіставте сумарні хвилини задач із доступним часом зміни.</p><a class="tool-primary" href="/tools/housekeeping-workload-calculator/">Порахувати навантаження ↗</a></article><article class="tool-card"><h3>Вплив скасування</h3><p>Порівняйте плановий внесок з нетто-утриманням і повторним продажем дат.</p><a class="tool-primary" href="/tools/hotel-cancellation-cost-calculator/">Порівняти сценарій ↗</a></article></div></section><p class="tool-note">');
 html=html.replace('<p class="tool-note">','<section class="tool-library-link"><h2>Відповіді на відгуки</h2><p>Скористайтеся нейтральним шаблоном на основі підтверджених фактів. <a href="/tools/hotel-review-response/">Підготувати чернетку відповіді</a>.</p></section><p class="tool-note">');
 html=html.replace('<p class="tool-note">',`<section class="tool-added-catalog"><h2>Шаблони для роботи готелю</h2><div class="tool-catalog-grid">${worksheetTools.map(tool=>`<article class="tool-card"><span class="tool-card-tag">ШАБЛОН XLSX</span><h3>${esc(tool.heading)}</h3><p>${esc(tool.description)}</p><a class="tool-primary" href="${esc(tool.path)}">Відкрити шаблон <span aria-hidden="true">↗</span></a></article>`).join('')}</div></section><p class="tool-note">`);
 html=html.replace('<p class="tool-note">',`<section class="tool-library-link"><h2>Річний бюджет PMS</h2><p>Порахуйте регулярні платежі, запуск і час команди в <a href="${pmsCostPath}">калькуляторі повної вартості PMS</a>.</p></section><p class="tool-note">`);
 html=html.replace('<p class="tool-note">',`<section class="tool-added-catalog"><h2>Калькулятори для рецепції та продажів</h2><div class="tool-catalog-grid">${operationCalculators.map(tool=>`<article class="tool-card"><span class="tool-card-tag">КАЛЬКУЛЯТОР</span><h3>${esc(tool.title)}</h3><p>${esc(tool.description)}</p><a class="tool-primary" href="${esc(tool.path)}">Відкрити калькулятор <span aria-hidden="true">↗</span></a></article>`).join('')}</div></section><p class="tool-note">`);
 return addToolCatalogIcons(html);
}

export function renderHotelProfitabilityCalculator(){
 let html=headMeta(shell(),{title:'Калькулятор прибутковості готелю: виручка та RevPAR | VDALO',description:'Оцініть місячну виручку, RevPAR, комісію онлайн-агентств бронювання та витрати на енергію. Безкоштовний калькулятор для готельєрів.',path:'/tools/hotel-profitability-calculator/'});
 html=html.replace(/<main id="main">[\s\S]*?<\/main>/,`<main id="main" class="tool-page profitability-page"><div class="tool-wrap">${breadcrumb('Калькулятор прибутковості готелю')}<header class="tool-hero profitability-hero"><p class="tool-kicker">ФІНАНСОВІ ПОКАЗНИКИ ГОТЕЛЮ</p><h1>Калькулятор виручки, RevPAR та витрат готелю</h1><p>Введіть середні показники за місяць і побачте орієнтовну виручку, RevPAR, комісію онлайн-агентств бронювання (OTA) та витрати на енергію.</p><a class="tool-primary" href="#profitability-calculator">Порахувати <span aria-hidden="true">↓</span></a></header><section class="profitability-intro"><h2>Порахуйте сценарій свого готелю</h2><p>Калькулятор працює з 30-денним місяцем. Змініть будь-яке поле, щоб одразу побачити, як змінюється оцінка.</p></section><section id="profitability-calculator" class="profitability-calculator" data-profitability-calculator aria-labelledby="profitability-title"><div class="profitability-inputs"><div class="profitability-panel-heading"><p class="tool-card-tag">ВАШІ ВИХІДНІ ДАНІ</p><h2 id="profitability-title">Параметри місяця</h2><p>Початкові значення можна змінити на ваші.</p></div><div class="profitability-fields">${[
  ['rooms','Кількість номерів',10,200,1,40,'номерів'],['occupancy','Середня завантаженість',10,100,1,55,'%'],['adr','Середній тариф за ніч',1000,10000,100,3000,'₴'],['energy','Енерговитрати на зайнятий номер за ніч',100,2000,50,400,'₴'],['otaShare','Частка бронювань через онлайн-агентства (OTA)',0,100,1,60,'%'],['otaCommission','Середня комісія OTA',10,25,0.5,18,'%']
 ].map(([key,label,min,max,step,value,unit])=>`<div class="profitability-field"><div class="profitability-field-label"><label for="profit-${key}">${label}</label><div class="profitability-number"><input id="profit-${key}" type="number" inputmode="decimal" min="${min}" max="${max}" step="any" value="${value}" data-profit-value="${key}" aria-describedby="profit-${key}-unit" required><span id="profit-${key}-unit">${unit}</span></div></div><input type="range" min="${min}" max="${max}" step="${step}" value="${value}" data-profit-range="${key}" aria-label="${label}"></div>`).join('')}</div><p class="profitability-hint">Показники орієнтовні. Введіть середні значення, а не дані конкретних гостей.</p><p class="profitability-status" data-profit-status role="status" aria-live="polite"></p></div><div class="profitability-results" aria-live="polite"><p class="tool-card-tag">ОЦІНКА ЗА 30 ДНІВ</p><h2>Орієнтовний залишок після комісій OTA та енергії</h2><p class="profitability-total" data-profit-result="remaining">-</p><p class="profitability-total-caption">Показує залишок після комісії OTA та витрат на енергію. Додайте решту операційних статей у своїй фінансовій моделі, щоб оцінити прибуток.</p><div class="profitability-kpis"><article><span>Валова виручка</span><strong data-profit-result="revenue">-</strong></article><article><span>RevPAR</span><strong data-profit-result="revpar">-</strong><small>виручка на доступний номер за добу</small></article><article><span>Продані номероночі</span><strong data-profit-result="soldNights">-</strong></article></div><div class="profitability-breakdown"><h3>Статті розрахунку</h3><div class="profitability-bar-row"><div><span>Валова виручка</span><strong data-profit-result="revenueRow">-</strong></div><span class="profitability-track"><span data-profit-bar="revenue"></span></span></div><div class="profitability-bar-row"><div><span>Оцінка комісії OTA</span><strong data-profit-result="commission">-</strong></div><span class="profitability-track"><span data-profit-bar="commission"></span></span></div><div class="profitability-bar-row"><div><span>Енерговитрати</span><strong data-profit-result="energyCost">-</strong></div><span class="profitability-track"><span data-profit-bar="energy"></span></span></div><div class="profitability-bar-row"><div><span>Після цих двох статей</span><strong data-profit-result="remainingRow">-</strong></div><span class="profitability-track"><span data-profit-bar="remaining"></span></span></div><p class="profitability-scale-note">Довжина смуг показує співвідношення сум у цьому сценарії.</p></div></div></section><p class="profitability-disclaimer">Щоб оцінити прибуток, додайте зарплати, податки, оренду, ремонт, закупівлі, інші комісії та сезонність до своєї фінансової моделі. Комісію OTA калькулятор рахує як частку бронювань, помножену на введену ставку. Для точного бюджету використовуйте фактичні умови каналів.</p><section class="tool-method profitability-explainer"><h2>Що означають показники</h2><div class="profitability-definitions"><article><h3>Валова виручка</h3><p>Кількість зайнятих номероночей за місяць, помножена на середній тариф за ніч.</p></article><article><h3>RevPAR</h3><p>Валова виручка, поділена на всі доступні номероночі. Це допоміжний показник виручки, а не прибутку.</p></article><article><h3>Комісія OTA</h3><p>OTA (Online Travel Agency) означає онлайн-агентство бронювання. Суму комісії оцінено за заданими часткою таких бронювань і середньою ставкою.</p></article><article><h3>Залишок у калькуляторі</h3><p>Валова виручка мінус оцінка комісії OTA та введені енерговитрати. Для GOPPAR потрібні повні операційні витрати, тому калькулятор його не показує.</p></article></div></section><section class="profitability-next-step"><div><p class="tool-card-tag">НАСТУПНИЙ КРОК</p><h2>Потрібно розібратися, де у вашому процесі виникають витрати?</h2><p>Обговоримо роботу готелю й визначимо, які процеси варто перевірити докладніше.</p></div><a class="tool-primary" href="/#audit">Отримати безкоштовний аудит <span aria-hidden="true">↗</span></a></section><section class="tool-sources"><h2>Пов’язані матеріали</h2><p>Перегляньте <a href="/pricing">тарифи VDALO</a>, <a href="/integrations">можливості підключення каналів</a> або <a href="/blog">статті для готельєрів</a>. Якщо ви плануєте зміни в операціях, прочитайте <a href="/blog/shcho-avtomatyzuvaty-v-goteli-pershym">як визначити, що автоматизувати в готелі першим</a>.</p></section></div></main>`);
 html=html.replace('<p class="profitability-disclaimer">','<details class="kpi-extension" data-hotel-kpis><summary>Інші показники: TRevPAR, GOPPAR, TRevPAB, ALOS та індекс</summary><p>Заповнюйте лише ті поля, для яких маєте однакову й перевірену базу. Доступні номероночі, ліжко-доби та група бронювань описують різні одиниці. Не змішуйте їх у розрахунках.</p><div class="tool-form-grid"><label>Доступні номеро-ночі<input type="number" min="1" max="1000000000" step="1" data-kpi-rooms></label><label>Загальний дохід за той самий період, грн<input type="number" min="0" max="1000000000000" step="0.01" data-kpi-revenue></label><label>GOP, грн за той самий період<input type="number" min="-1000000000000" max="1000000000000" step="0.01" data-kpi-gop></label><label>Доступні ліжко-доби<input type="number" min="1" max="1000000000" step="1" data-kpi-beds></label><label>Номероночі однієї групи бронювань<input type="number" min="0" max="1000000000" step="1" data-kpi-cohort-nights></label><label>Кількість бронювань тієї самої групи<input type="number" min="1" max="1000000000" step="1" data-kpi-cohort-bookings></label><label>Ваш зіставний показник<input type="number" min="0" max="1000000000000" step="0.01" data-kpi-own></label><label>Показник зіставної групи<input type="number" min="0.000001" max="1000000000000" step="0.01" data-kpi-peer></label><label>Тип індексу<select data-kpi-index-type><option value="MPI">MPI, завантаження</option><option value="ARI">ARI, середній тариф</option><option value="RGI">RGI, RevPAR</option></select></label></div><p class="tool-inline-error" data-kpi-error role="alert"></p><div class="tool-actions"><button class="tool-primary" type="button" data-kpi-calculate>Порахувати заповнені показники</button><button class="tool-secondary" type="button" data-kpi-export disabled>Завантажити CSV</button></div><div class="kpi-results" data-kpi-results hidden aria-live="polite"><h3>Показники за вашими даними</h3><dl><div><dt>TRevPAR</dt><dd data-kpi-out="tRevpar">Немає даних</dd></div><div><dt>GOPPAR</dt><dd data-kpi-out="goppar">Немає даних</dd></div><div><dt>TRevPAB</dt><dd data-kpi-out="tRevPab">Немає даних</dd></div><div><dt>ALOS</dt><dd data-kpi-out="alos">Немає даних</dd></div><div><dt data-kpi-index-label>Індекс</dt><dd data-kpi-out="index">Немає даних</dd></div></dl><p>Індекс не є ринковим порівнянням VDALO. Порівнюйте лише однакові періоди, метрики й зіставну групу. Нульовий знаменник не дає індексу.</p></div></details><p class="profitability-disclaimer">');
 return html;
}

function simpleScenarioPage({title,description,path,kicker,heading,intro,fields,id,results,formula}){
 let html=headMeta(shell(),{title,description,path});
 const inputMarkup=fields.map(([key,label,value,min,max,step,unit,hint])=>`<label class="scenario-field" for="${id}-${key}"><span>${esc(label)}</span><span class="scenario-input"><input id="${id}-${key}" data-scenario-input="${key}" type="number" inputmode="decimal" min="${min}" max="${max}" step="${step}" value="${value}" required><small>${esc(unit)}</small></span>${hint?`<small class="scenario-help">${esc(hint)}</small>`:''}</label>`).join('');
 const resultMarkup=results.map(([key,label])=>`<div class="scenario-result"><span>${esc(label)}</span><strong data-scenario-result="${key}">Очікує розрахунку</strong></div>`).join('');
 const guidance={
  'channel-economics':`<section class="tool-method"><h2>Приклад порівняння каналів</h2><p>У навчальному сценарії проживання коштує 6 000 грн, комісія OTA – 15%, знижка прямого каналу – 5%, комісія платіжного сервісу – 2%, а залучення прямого бронювання – 200 грн. Інші задані витрати дорівнюють нулю. Внесок OTA становить 5 100 грн, прямого каналу – 5 386 грн: різниця 286 грн на користь прямого каналу.</p><p>За цих самих умов граничні витрати залучення для рівності внесків становлять 486 грн. Якщо показник від’ємний, прямий канал поступається навіть за нульових витрат на залучення. Приклад не враховує інші можливі витрати та не прогнозує результат готелю.</p><h3>Які дані порівнювати</h3><p>Візьміть однакове проживання та період, узгодьте склад тарифу й податків. Розподіліть витрати маркетингу на завершені прямі проживання за обраною методикою та не додавайте одну витрату двічі. Якщо змінні витрати відрізняються за каналами, врахуйте різницю в інших витратах відповідного каналу.</p><p>Детальніше: <a href="/blog/pryami-bronyuvannya-ta-vidzhet-gotelyu">як перевіряти прямі бронювання та віджет</a> і <a href="/cases/direct-bookings-calendar">кейс прямих бронювань глемпінгу</a>.</p></section>`,
  'room-cost':`<section class="tool-method"><h2>Приклад беззбитковості</h2><p>Для фонду 600 номероночей за період, постійних витрат 300 000 грн, тарифу 1 800 грн, змінних витрат 350 грн за продану ніч і витрат розподілу 10% внесок однієї ночі дорівнює 1 270 грн. Для покриття врахованих витрат потрібно щонайменше 237 цілих номероночей, тобто 39,5% фонду. Це навчальний сценарій.</p><h3>Як підготувати свої дані</h3><p>Використовуйте один період для фонду, продажів і витрат. Відніміть із фонду недоступні для продажу ночі за однаковим правилом. Витрати, що змінюються з кожним продажем, внесіть окремо від постійних, а комісії не рахуйте двічі. Якщо за період не продано жодної номероночі, витрати на одну продану ніч визначити неможливо.</p><p>Модель показує покриття лише введених витрат. Для повного фінансового висновку звірте склад витрат, податки та інші доходи зі своєю звітністю. Далі можна оцінити <a href="/tools/hotel-profitability-calculator/">виручку й RevPAR</a> або порівняти <a href="/tools/direct-booking-cost-calculator/">економіку OTA та прямого каналу</a>.</p></section>`,
 };
 html=html.replace(/<main id="main">[\s\S]*?<\/main>/,`<main id="main" class="tool-page"><div class="tool-wrap">${breadcrumb(heading)}<header class="tool-hero"><p class="tool-kicker">${esc(kicker)}</p><h1>${esc(heading)}</h1><p>${esc(intro)}</p></header><section class="scenario-app" data-scenario="${id}" aria-labelledby="${id}-form-title"><div class="scenario-inputs"><h2 id="${id}-form-title">Ваші припущення</h2><p>Початкові значення наведені лише як навчальний приклад. Замініть їх даними одного й того самого періоду.</p><div class="scenario-fields">${inputMarkup}</div><p class="scenario-error" data-scenario-error role="alert"></p><div class="tool-actions"><button class="tool-primary" type="button" data-scenario-calculate>Порахувати сценарій</button><button class="tool-secondary" type="button" data-scenario-export disabled>Завантажити CSV</button></div></div><section class="scenario-output" aria-live="polite"><p class="tool-card-tag">РЕЗУЛЬТАТ ЗА ВАШИМИ ДАНИМИ</p><div class="scenario-results">${resultMarkup}</div><p class="scenario-summary" data-scenario-summary>Введіть припущення й натисніть «Порахувати сценарій».</p></section></section><section class="tool-method"><h2>Як читати результат</h2><p>${esc(formula)}</p><p>Це навчальна модель за введеними вами припущеннями, а не прогноз, гарантія доходу чи бухгалтерський висновок. Не вводьте дані гостей або конфіденційні комерційні відомості.</p></section>${guidance[id]||''}<section class="tool-sources"><h2>Далі за темою</h2><p><a href="/tools/">Переглянути інші інструменти</a> або <a href="/contact">обговорити процеси свого об’єкта</a>.</p></section></div></main>`);
 return html;
}

export function renderDirectBookingCostCalculator(){
 return simpleScenarioPage({title:'Комісія OTA чи пряме бронювання: калькулятор | VDALO',description:'Порівняйте внесок OTA та прямого бронювання з урахуванням комісій, знижки, еквайрингу й залучення. Введіть власні припущення.',path:'/tools/direct-booking-cost-calculator/',kicker:'ЕКОНОМІКА КАНАЛІВ БРОНЮВАННЯ',heading:'Скільки залишається від бронювання через різні канали',intro:'Порівняйте одне завершене проживання через OTA та прямий канал. Усі тарифи й витрати задаєте ви.',id:'channel-economics',fields:[['baseRevenue','Виручка за завершене проживання',6000,0.01,100000000,0.01,'грн','Однакова база до витрат каналу.'],['otaFeePct','Комісія OTA',15,0,100,0.1,'%','Навчальне припущення, не тариф конкретного сервісу.'],['directDiscountPct','Знижка прямого каналу',5,0,99.99,0.1,'%','Не може дорівнювати 100%.'],['directPspPct','Комісія платіжного сервісу',2,0,100,0.1,'%','Модель від виручки прямого каналу.'],['directAcquisitionCost','Залучення прямого бронювання',200,0,100000000,0.01,'грн','Витрати на одне завершене проживання.'],['variableStayCost','Однакові змінні витрати проживання',0,0,100000000,0.01,'грн','Вираховуються з обох каналів.'],['otaOtherCosts','Інші витрати OTA',0,0,100000000,0.01,'грн','Вводьте фактичну суму.'],['directOtherCosts','Інші витрати прямого каналу',0,0,100000000,0.01,'грн','Не дублюйте комісію платіжного сервісу.']],results:[['otaContribution','Внесок через OTA'],['directContribution','Внесок через прямий канал'],['difference','Різниця: прямий мінус OTA'],['maxAcquisitionCost','Граничні витрати на залучення для рівності']],formula:'Внесок OTA = виручка − комісія OTA − спільні змінні витрати − інші витрати OTA. Внесок прямого каналу = виручка після знижки − платіжна комісія − залучення − спільні змінні витрати − інші витрати прямого каналу. Від’ємна різниця означає, що в цьому сценарії прямий канал дав менший внесок.'});
}

export function renderHotelRoomCostCalculator(){
 return simpleScenarioPage({title:'Собівартість номера і беззбитковість готелю | VDALO',description:'Оцініть витрати на продану номероніч і завантаження для покриття введених витрат. Модель працює з вашими припущеннями.',path:'/tools/hotel-room-cost-calculator/',kicker:'ВИТРАТИ ТА ЗАВАНТАЖЕННЯ',heading:'Собівартість номера та точка беззбитковості',intro:'Подивіться, яке завантаження покриває саме враховані вами витрати. Період витрат і номероночей має збігатися.',id:'room-cost',fields:[['availableRoomNights','Доступний фонд',600,1,1000000000,1,'номероніч','Наприклад, фонд за обраний місяць.'],['soldRoomNights','Продані номероночі',300,0,1000000000,1,'номероніч','Не більше за доступний фонд.'],['fixedCosts','Постійні витрати за період',300000,0,1000000000000,0.01,'грн','Врахуйте період і не дублюйте змінні статті.'],['variablePerSoldNight','Змінні витрати на продану ніч',350,0,1000000000,0.01,'грн','Лише витрати, що змінюються з продажем.'],['adr','Середній тариф за продану ніч',1800,0.01,1000000000,0.01,'грн','За той самий період і базу виручки.'],['distributionPct','Витрати розподілу від виручки',10,0,99.99,0.1,'%','Вкажіть власну оцінку; не додавайте сюди витрати, вже включені в постійні.']],results:[['revenue','Виручка за номероночі'],['costPerSoldNightBeforeDistribution','Витрати на ніч до витрат розподілу'],['costPerSoldNightAfterDistribution','Витрати на ніч після витрат розподілу'],['resultAfterIncludedCosts','Результат після врахованих витрат'],['breakEvenRoomNights','Номероночі для беззбитковості'],['breakEvenOccupancyPct','Завантаження для беззбитковості']],formula:'Виручка = тариф × продані номероночі. Внесок однієї проданої ночі = тариф × (1 − частка витрат розподілу) − змінні витрати. Беззбитковість = постійні витрати ÷ внесок однієї ночі. Якщо внесок не додатний або потрібне завантаження перевищує 100%, задані умови не дають досягти беззбитковості.'});
}

const roomAcceptanceItems=[
 ['H01','Білизна та рушники відповідають стандарту',true],['H02','Санвузол очищено за внутрішнім стандартом',true],['H03','Немає видимих небезпечних пошкоджень',true],['H04','Замок і спосіб доступу перевірені',true],['H05','Вода й сантехніка працюють',true],['H06','Робота освітлення перевірена',false],['H07','Підлога й доступні поверхні чисті',false],['H08','Меблі без нових видимих пошкоджень',false],['H09','Сміття прибране й кошики підготовлені',false],['H10','Витратні матеріали укомплектовані',false],['H11','Вікна та штори перевірені',false],['H12','Кліматичне обладнання перевірено за наявності',false],['H13','Техніка перевірена за комплектацією',false],['H14','Інформаційні матеріали актуальні',false],['H15','Контакти рецепції доступні',false],['H16','Пляшки й посуд підготовлені за стандартом',false],['H17','Запах і провітрювання перевірені',false],['H18','Забуті речі передані за процедурою',false],['H19','Зауваження попередньої зміни опрацьовані',false],['H20','Повторна перевірка виправлень виконана',false],
];

export function renderHousekeepingChecklist(){
 const html=headMeta(shell(),{title:'Чекліст перевірки номера перед заселенням | VDALO',description:'Створіть картку перевірки номера, позначте критичні питання, надрукуйте її або збережіть локальним JSON. Готовність підтверджує відповідальна людина.',path:'/tools/housekeeping-checklist/'});
 return html.replace(/<main id="main">[\s\S]*?<\/main>/,`<main id="main" class="tool-page"><div class="tool-wrap">${breadcrumb('Чекліст приймання номера')}<header class="tool-hero"><p class="tool-kicker">КАРТКА ПЕРЕДАВАННЯ КОМАНДІ</p><h1>Перевірте номер перед передаванням рецепції</h1><p>Позначте стан кожного пункту та додайте зауваження. Адаптуйте картку до правил свого об’єкта, а перед передаванням номера попросіть відповідального працівника підтвердити результат огляду.</p></header><section class="housekeeping-app" data-housekeeping><div class="housekeeping-meta"><label>Внутрішній код приміщення, необов’язково<input maxlength="40" data-room-alias autocomplete="off"></label><label>Дата перевірки<input type="date" data-room-date></label><label>Роль перевіряча, необов’язково<input maxlength="60" data-room-role autocomplete="off"></label></div><p class="tool-note">Позначте критичні пункти за стандартом вашого готелю, щоб картка відповідала процесу приймання номера.</p><div class="housekeeping-items">${roomAcceptanceItems.map(([id,title,critical])=>`<fieldset class="housekeeping-item" data-housekeeping-item="${id}"><legend><span>${id}. ${esc(title)}</span></legend><label class="housekeeping-critical"><input type="checkbox" data-critical="${id}" ${critical?'checked':''}><span>Критично для рішення про передавання</span></label><label class="housekeeping-status">Стан<select data-room-status="${id}"><option value="not_checked">Не перевірено</option><option value="pass">Перевірено</option><option value="fail">Є зауваження</option><option value="not_applicable">Не застосовується</option></select></label><label class="housekeeping-note">Зауваження, необов’язково<textarea rows="2" maxlength="300" data-room-note="${id}" placeholder="Без імен, контактів гостей або кодів доступу"></textarea></label><label class="housekeeping-na-reason" data-na-wrap="${id}" hidden>Поясніть, чому пункт не застосовується<textarea rows="2" maxlength="240" data-room-na-reason="${id}"></textarea></label></fieldset>`).join('')}</div><div class="tool-actions"><button class="tool-primary" type="button" data-room-check>Показати підсумок</button><button class="tool-secondary" type="button" data-room-print>Роздрукувати картку</button><button class="tool-secondary" type="button" data-room-export>Завантажити JSON</button><button class="tool-secondary" type="button" data-room-reset>Очистити картку</button></div><section class="housekeeping-result" data-room-result hidden aria-live="polite"><h2 data-room-result-title></h2><p data-room-result-copy></p><ul data-room-blockers></ul><p class="tool-note">Остаточне рішення щодо готовності приймає відповідальна людина після фізичної перевірки.</p></section></section><section class="tool-method"><h2>Як працює підсумок</h2><p>Картка підсвічує неперевірені критичні пункти й збирає зауваження. Після огляду відповідальний працівник переглядає підсумок і підтверджує готовність номера для наступного заїзду. Якщо зміните позначки після перегляду, сформуйте підсумок повторно.</p><p>Для планування зміни скористайтеся <a href="/tools/housekeeping-workload-calculator/">калькулятором навантаження прибирання</a>, а для налаштування передачі статусів прочитайте <a href="/blog/status-gotovnosti-nomera-housekeeping">матеріал про готовність номера</a>.</p><p>Заповнені поля залишаються у відкритій сторінці браузера. Інструмент не надсилає їх на сервер і не передає в аналітику. Завантажений JSON зберігається на вашому пристрої.</p></section><section class="tool-sources"><h2>Матеріали за темою</h2><p>Завантажте <a href="/downloads/hotel/room_acceptance.txt">текстову картку приймання номера</a> або перегляньте <a href="/resources">бібліотеку шаблонів</a>.</p></section></div></main>`);
}

function pmsTcoSection(){
 const proposals=[1,2,3].map(i=>`<fieldset class="tco-proposal" data-tco-proposal="${i}"><legend>Пропозиція ${i}</legend><div class="tool-form-grid"><label>Назва для порівняння<input maxlength="80" data-tco-name="${i}" required></label><label>Підписка за місяць, грн<input type="number" min="0" max="1000000000" step="0.01" data-tco-value="${i}|baseMonthly" required></label><label>Модулі за місяць, грн<input type="number" min="0" max="1000000000" step="0.01" data-tco-value="${i}|modulesMonthly" required></label><label>Підключення, грн разово<input type="number" min="0" max="1000000000" step="0.01" data-tco-value="${i}|setup" required></label><label>Перенесення даних, грн разово<input type="number" min="0" max="1000000000" step="0.01" data-tco-value="${i}|migration" required></label><label>Обладнання, грн разово<input type="number" min="0" max="1000000000" step="0.01" data-tco-value="${i}|hardware" required></label><label>Платежі за використання за весь період, грн<input type="number" min="0" max="1000000000000" step="0.01" data-tco-value="${i}|usageTotal" required></label><label>Поновлення за весь період, грн<input type="number" min="0" max="1000000000000" step="0.01" data-tco-value="${i}|renewalsTotal" required></label><label>Внутрішній час, год<input type="number" min="0" max="1000000000" step="0.01" data-tco-value="${i}|internalHours" required></label><label>Оцінка внутрішньої години, грн<input type="number" min="0" max="10000000" step="0.01" data-tco-value="${i}|hourCost" required></label></div></fieldset>`).join('');
 return `<section class="tco-extension" data-pms-tco><h2>TCO: повна вартість PMS</h2><p>Порівняйте дві або три письмові пропозиції на однаковому горизонті. Невідому ціну не замінюйте нулем. Валюта всіх сум має бути однаковою.</p><label class="tco-horizon">Період порівняння, місяців<input type="number" min="1" max="60" step="1" value="12" data-tco-months required></label><p class="tool-note">У полі платежів за використання введіть суму за весь горизонт. У поновленнях вкажіть фактичну суму за графіком за весь горизонт. Внутрішній час показується окремим ресурсом і не входить у грошові витрати.</p>${proposals}<p class="tool-inline-error" data-tco-error role="alert"></p><div class="tool-actions"><button class="tool-primary" type="button" data-tco-calculate>Порівняти повну вартість</button><button class="tool-secondary" type="button" data-tco-export disabled>Завантажити CSV</button></div><section data-tco-results class="tco-results" hidden aria-live="polite"><h3>Порівняння за введеними умовами</h3><div data-tco-output></div><p>Це суми за введеними вами пропозиціями, а не актуальний прайс VDALO чи рекомендація обрати дешевшу систему. Перед рішенням уточніть невідомі пункти в постачальника.</p></section></section>`;
}
export function renderPmsChecklist(){
 const emailReady=reportEmailReady();
 const reportDescription=emailReady?'Порівняйте до 3 PMS за 25 критеріями, перевірте ризики, отримайте персональний результат і повний звіт на email.':'Порівняйте до 3 PMS за 25 критеріями, перевірте ризики та отримайте персональний результат у браузері.';
 let html=headMeta(shell(),{title:'Чекліст вибору PMS: 25 критеріїв | VDALO',description:reportDescription,path:'/tools/pms-checklist/'});
 html=html.replace(/<main id="main">[\s\S]*?<\/main>/,`<main id="main" class="tool-page"><div class="tool-wrap">${breadcrumb('Чекліст вибору PMS')}<header class="tool-hero"><p class="tool-kicker">ПЕРЕД ДЕМОНСТРАЦІЄЮ АБО ЗМІНОЮ СИСТЕМИ</p><h1>Чекліст вибору PMS: оцініть систему за 25 критеріями</h1><p>Порівняйте до трьох PMS за однаковими практичними сценаріями. Відмічайте лише те, що вдалося перевірити, і зберігайте власні висновки в браузері.</p><a class="tool-primary" href="#checklist-start" data-tool-start>Почати перевірку <span aria-hidden="true">↓</span></a></header><section class="tool-method"><h2>Як працює оцінювання</h2><p><strong>Підтверджено</strong> дає 2 бали, <strong>Частково</strong> 1, <strong>Не пройдено</strong> 0. «Не перевірено» залишається невідомим, а «Не застосовується» виключається з розрахунку. Результат показує оцінку та повноту перевірки разом.</p><p>Оцінки та примітки зберігаються лише в цьому браузері. Не додавайте персональні дані гостей, паролі, платіжні дані або секрети інтеграцій. Повний результат можна переглянути та надрукувати без реєстрації.</p></section><section id="checklist-start" class="checklist-app" data-pms-checklist data-email-ready="${emailReady}"><noscript><p>Для роботи інтерактивного чекліста увімкніть JavaScript. Опис 25 критеріїв доступний нижче.</p></noscript><div class="checklist-intro"><h2>Підготуйте порівняння</h2><p>Назва першої системи обов’язкова. Інші поля можна заповнити пізніше.</p><div class="tool-form-grid"><label>Назва PMS №1 <input data-pms-name="0" maxlength="80" required autocomplete="off" placeholder="Наприклад, моя поточна система"></label><label>Назва PMS №2 <input data-pms-name="1" maxlength="80" autocomplete="off" placeholder="Необов’язково"></label><label>Назва PMS №3 <input data-pms-name="2" maxlength="80" autocomplete="off" placeholder="Необов’язково"></label><label>Назва готелю <input data-hotel maxlength="100" autocomplete="organization" placeholder="Необов’язково"></label><label>Тип об’єкта <input data-property maxlength="80" placeholder="Готель, апарт-готель…"></label><label>Кількість номерів <input data-rooms type="number" min="1" max="99999" inputmode="numeric"></label></div><p class="tool-inline-error" data-setup-error role="alert"></p><div class="tool-actions"><button class="tool-primary" type="button" data-begin>Почати оцінювання</button><button class="tool-secondary" type="button" data-reset>Очистити збережені дані</button></div></div><div class="checklist-work" data-work hidden><div class="checklist-topline"><span data-group-label></span><span data-progress aria-live="polite"></span></div><div class="tool-progress" aria-hidden="true"><span data-progress-bar></span></div><div data-group-content></div><p class="tool-inline-error" data-group-error role="alert"></p><div class="tool-actions tool-actions-between"><button class="tool-secondary" type="button" data-prev>Назад</button><button class="tool-primary" type="button" data-next>Далі</button><button class="tool-primary" type="button" data-finish hidden>Завершити оцінювання</button></div></div><div class="checklist-results" data-results hidden aria-live="polite"></div><div class="report-wrap" data-report-wrap hidden><form data-report-form method="post" action="/api/tools/pms-report"><h3>Отримати повний звіт на email</h3><p>Надішлемо підсумок і повну матрицю оцінок на вказану адресу.</p><label>Email для звіту<input type="email" name="email" autocomplete="email" maxlength="254" required></label><label class="honeypot" aria-hidden="true">Не заповнюйте це поле<input name="website" tabindex="-1" autocomplete="off"></label><label class="report-consent"><input type="checkbox" name="consent" required><span>Погоджуюся на обробку адреси email для надсилання звіту згідно з <a href="/privacy">політикою конфіденційності</a>.</span></label><button class="tool-primary" type="submit">Надіслати звіт</button><p data-report-status role="status" aria-live="polite"></p></form></div></section><section class="tool-criteria-reference"><h2>25 критеріїв, які ви перевірите</h2>${pmsCriteria.map(g=>`<section><h3>${esc(g.name)}</h3><ol>${g.criteria.map(c=>`<li><strong>${esc(c.title)}</strong><span>Як перевірити: ${esc(c.howToVerify)}. Вага за замовчуванням: ${c.weight}.</span></li>`).join('')}</ol></section>`).join('')}</section><section class="tool-faq"><h2>Поширені запитання</h2><details><summary>Що оцінює чекліст?</summary><p>25 практичних аспектів роботи PMS: від бронювань та доступності номерів до безпеки, підтримки, договору й повної вартості.</p></details><details><summary>Чи можна порівняти 2-3 PMS?</summary><p>Так. Назвіть одну, дві або три системи й оцінюйте кожну за однаковими критеріями. Переможця автоматично не визначаємо.</p></details><details><summary>Як працюють бали?</summary><p>Підтверджено: 2, частково: 1, не пройдено: 0. Невідомі пункти не рахуються як нуль. Поруч завжди показується покриття перевіркою.</p></details><details><summary>Чи можна зберегти результат?</summary><p>Так. Прогрес зберігається локально у браузері. Ви можете продовжити пізніше, надрукувати підсумок або очистити його.</p></details></section><section class="tool-sources"><h2>Методика оцінювання</h2><p>Перелік критеріїв побудовано як практичну матрицю для демонстрації PMS. Бал відображає вашу оцінку за вибраними критеріями, а не незалежний аудит VDALO чи постачальника. Актуальність і склад вимог варто перевіряти для свого об’єкта.</p><p><a href="/blog/yak-obraty-pms-dlya-gotelyu">Читайте посібник «Як обрати PMS для готелю у 2026/2027 роках»</a> або <a href="/blog/shcho-take-pms-dlya-gotelyu">дізнайтеся, що таке PMS</a>. Після відбору перевірте <a href="/integrations">сумісність потрібних інтеграцій</a> та <a href="/pricing">тарифи й склад витрат</a>.</p></section></div></main>`);
 html=html.replace('<section class="tool-criteria-reference">',pmsTcoSection()+'<section class="tool-criteria-reference">');
 return html;
}
